    d = {"a": 2, "b": 3, "c": 4}
    prices = {"a": 1.5, "b": 2.0}
    assert inv.total_value(d, prices) == 2 * 1.5 + 3 * 2.0


if __name__ == "__main__":
    test_add_accumulates()
